func csilDecCancelRequest(csilRoot cborValue) (CancelRequest, error) {
	var csilOut CancelRequest
	{
		csilField, csilErr := cborRequire(csilRoot, "id")
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilVal, csilErr := (cborAsText)(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.Id = csilVal
	}
	if csilField, csilOk := cborMapGet(csilRoot, "reason"); csilOk {
		csilVal, csilErr := (cborAsText)(csilField)
		if csilErr != nil {
			return csilOut, csilErr
		}
		csilOut.Reason = &csilVal
	}
	return csilOut, nil
}

// EncodeCancelRequest encodes a CancelRequest to canonical CSIL CBOR bytes.
func EncodeCancelRequest(csilV CancelRequest) []byte {
	return cborEncode(csilEncCancelRequest(csilV))
}

// DecodeCancelRequest decodes canonical CSIL CBOR bytes into a CancelRequest.
func DecodeCancelRequest(csilData []byte) (CancelRequest, error) {
	csilRoot, csilErr := cborDecode(csilData)
	if csilErr != nil {
		var csilZero CancelRequest
		return csilZero, csilErr
	}
	return csilDecCancelRequest(csilRoot)
}
